import "aos/dist/aos.css";
import {
    FaFileSignature,
    FaBuilding,
    FaBalanceScale,
    FaHandshake,
    FaClipboardCheck,
    FaStamp,
    FaWhatsapp,
} from "react-icons/fa";
import AppContext from "../../../Context";
import { useContext } from "react";

function Notary() {
    //-----------------------STATE VIEWS-----------------------//
    const { language } = useContext(AppContext);
    const notaryServices = [
        {
            title:
                language === "id"
                    ? "Akta Pendirian Perusahaan"
                    : "Deed of Establishment",
            description:
                language === "id"
                    ? "Pembuatan akta pendirian perusahaan sesuai dengan peraturan perundang-undangan untuk memastikan legalitas usaha Anda."
                    : "Preparation of company establishment deeds in accordance with applicable laws to ensure your business legality.",
            icon: FaBuilding,
        },
        {
            title:
                language === "id"
                    ? "Akta Perubahan"
                    : "Deed Amendment",
            description:
                language === "id"
                    ? "Proses resmi perubahan anggaran dasar dan data perusahaan melalui akta notaris."
                    : "Official processing of amendments to articles of association and company data through a notarial deed.",
            icon: FaFileSignature,
        },
        {
            title:
                language === "id"
                    ? "Perjanjian Pemegang Saham"
                    : "Shareholder Agreement",
            description:
                language === "id"
                    ? "Penyusunan dan legalisasi perjanjian pemegang saham untuk memastikan transparansi dan perlindungan hukum."
                    : "Drafting and legalization of shareholder agreements to ensure transparency and legal protection.",
            icon: FaHandshake,
        },
        {
            title:
                language === "id"
                    ? "Legalisasi & Waarmerking"
                    : "Legalization & Waarmerking",
            description:
                language === "id"
                    ? "Legalisasi dan pendaftaran dokumen (waarmerking) untuk memberikan kekuatan hukum yang sah."
                    : "Legalization and registration of documents (waarmerking) to provide valid legal force.",
            icon: FaStamp,
        },
        {
            title:
                language === "id"
                    ? "Surat Kuasa"
                    : "Power of Attorney",
            description:
                language === "id"
                    ? "Pembuatan dokumen surat kuasa yang sah secara hukum untuk keperluan bisnis maupun pribadi."
                    : "Preparation of legally valid power of attorney documents for business or personal purposes.",
            icon: FaClipboardCheck,
        },
        {
            title:
                language === "id"
                    ? "Konsultasi Hukum"
                    : "Legal Consultation",
            description:
                language === "id"
                    ? "Layanan konsultasi hukum terkait notaris dan regulasi untuk mendukung kepastian hukum bisnis Anda."
                    : "Legal consultation services related to notarial matters and regulations to support your business legal certainty.",
            icon: FaBalanceScale,
        },
    ];

    const WA_NUMBER = "6281213094426";

    //------------------------FUNCTIONS------------------------//
    const getWaLink = (serviceName: string) => {
        const rawMessage =
            language === "id"
                ? `Halo Regarde,\nSaya ingin berkonsultasi mengenai layanan ${serviceName}.\nMohon informasi lebih lanjut. Terima kasih.`
                : `Hello Regarde,\nI would like to consult regarding the ${serviceName} service.\nPlease provide further information. Thank you.`;

        return `https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(rawMessage)}`;
    };
    //------------------------FUNCTIONS------------------------//

    return (
        <div className="pt-24">
            {/* NOTARY DETAIL */}
            <section data-aos="zoom-out" className="pb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-primary-blue-100 flex items-center justify-center">
                            <FaFileSignature className="text-primary-blue-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-primary-black-500 mb-4">
                        {language === "id" ? "Layanan Notaris" : "Notary Services"}
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-primary-black-500 max-w-2xl mx-auto mb-14">
                        {language === "id"
                            ? "Layanan notaris profesional untuk memastikan legalitas, kepastian hukum, dan perlindungan pada setiap dokumen serta transaksi bisnis."
                            : "Professional notary services to ensure legality, legal certainty, and protection for every document and business transaction."}
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {notaryServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-primary-blue-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-primary-black-500">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-primary-black-500 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition"
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </section>
        </div>
    );
}

export default Notary;